  const totals = invoiceTotals(result.value);

  const lineTotal = 10 * 8500; // 85000
  const discount = lineTotal * 20 / 100; // 17000
  const baseAmount = lineTotal - discount; // 68000
  const vat = Math.round(baseAmount * 21 / 100); // 14280
