});

test('createInvoice tier discount is correctly applied to multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'STICKER', qty: 100 },
    ],
