});

test('invoiceTotals correctly calculates with tier discounts', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  assert.equal(result.ok, true);

  const totals = invoiceTotals(result.value);
  const expectedSubtotal = 10 * 8500 + 5 * 9500; // 132500
  const expectedDiscount = (expectedSubtotal * 5) / 100; // 6625
  const expectedTotal = expectedSubtotal - expectedDiscount; // 125875

  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.total, expectedTotal);
});

test('lineVat calculates VAT on amount after discount', () => {
  const line = { qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 21 };
  const vat = lineVat(line);
  const lineTotal = 100 * 1000; // 100000
  const discount = lineTotal * 10 / 100; // 10000
  const baseAmount = lineTotal - discount; // 90000
  const expectedVat = Math.round(baseAmount * 21 / 100); // 18900
  assert.equal(vat, expectedVat);
});

test('lineVat rounds per line', () => {
  const line = { qty: 3, unitPrice: 1000, discountPercent: 0, vatRate: 21 };
  const vat = lineVat(line);
  const lineTotal = 3 * 1000; // 3000
  const expectedVat = Math.round(3000 * 21 / 100); // 630
  assert.equal(vat, expectedVat);
});

test('lineVat with 0% VAT rate', () => {
