  const vat = lineVat(line);
  assert.equal(vat, 0);
});

test('lineVat with 9% VAT rate', () => {
  const line = { qty: 50, unitPrice: 37, discountPercent: 0, vatRate: 9 };
  const vat = lineVat(line);
  const lineTotal = 50 * 37; // 1850
  const expectedVat = Math.round(1850 * 9 / 100); // 167 (rounded)
  assert.equal(vat, expectedVat);
});

test('lineVat clamps to 0', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 100, vatRate: 21 };
  const vat = lineVat(line);
  assert.equal(vat, 0);
});

test('invoiceTotals includes VAT and calculates total correctly', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'PRINT-A4', qty: 100 },
    ],
  });
  assert.equal(result.ok, true);

  const totals = invoiceTotals(result.value);

  const line1Total = 10 * 8500; // 85000
  const line1Vat = Math.round(85000 * 21 / 100); // 17850

  const line2Total = 100 * 37; // 3700
  const line2Vat = Math.round(3700 * 9 / 100); // 333

  const expectedSubtotal = line1Total + line2Total; // 88700
  const expectedVat = line1Vat + line2Vat; // 18183
  const expectedTotal = expectedSubtotal + expectedVat; // 106883

  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, expectedTotal);
});

test('invoiceTotals with discount and VAT', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 20 },
    ],
  });
  assert.equal(result.ok, true);

  const totals = invoiceTotals(result.value);

  const lineTotal = 10 * 8500; // 85000
  const discount = lineTotal * 20 / 100; // 17000
  const baseAmount = lineTotal - discount; // 68000
  const vat = Math.round(baseAmount * 21 / 100); // 14280
  const total = lineTotal - discount + vat; // 85000 - 17000 + 14280 = 82280

  assert.equal(totals.subtotal, lineTotal);
  assert.equal(totals.discount, discount);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, total);
});

test('invoiceTotals with mixed VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
